// src/components/Register.jsx
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom'; // ← Importer useNavigate

const Register = () => {
  const navigate = useNavigate(); // ← Ajouter useNavigate
  const [formData, setFormData] = useState({
    nom: '',
    email: '',
    password: '',
    role: '',
    class_id: ''
  });
  const [classes, setClasses] = useState([]);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');

  // Récupérer les classes au chargement
  useEffect(() => {
    fetchClasses();
  }, []);

  const fetchClasses = async () => {
    try {
      const response = await fetch('http://localhost:5000/api/classes/all');
      if (response.ok) {
        const classesData = await response.json();
        setClasses(classesData);
        console.log('📚 Classes chargées:', classesData.length);
      }
    } catch (error) {
      console.error('Erreur chargement classes:', error);
    }
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ 
      ...prev, 
      [name]: value 
    }));
  };

  const handleSubmit = async (e) => {
  e.preventDefault();
  setLoading(true);
  setMessage('');

  try {
    const response = await fetch('http://localhost:5000/api/auth/register', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(formData)
    });

    const result = await response.json();

    if (response.ok && result.success) {
      setMessage('✅ Compte créé avec succès! Vous allez être redirigé vers la page de connexion...');
      
      // Redirection après 3 secondes pour laisser voir le message
      setTimeout(() => {
        navigate('/login');
      }, 3000);
      
    } else {
      setMessage(`❌ Erreur: ${result.message}`);
    }
  } catch (error) {
    setMessage('❌ Erreur de connexion au serveur');
  } finally {
    setLoading(false);
  }
};




  return (
    <div style={{ maxWidth: '500px', margin: '50px auto', padding: '20px' }}>
      <h2>📝 Inscription</h2>
      
      {message && (
        <div style={{
          padding: '10px',
          backgroundColor: message.includes('✅') ? '#d4edda' : '#f8d7da',
          color: message.includes('✅') ? '#155724' : '#721c24',
          borderRadius: '5px',
          marginBottom: '20px'
        }}>
          {message}
        </div>
      )}

      <form onSubmit={handleSubmit}>
        <div style={{ marginBottom: '15px' }}>
          <label>👤 Nom complet *</label>
          <input
            type="text"
            name="nom"
            value={formData.nom}
            onChange={handleInputChange}
            required
            style={{ width: '100%', padding: '10px', marginTop: '5px' }}
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label>📧 Email *</label>
          <input
            type="email"
            name="email"
            value={formData.email}
            onChange={handleInputChange}
            required
            style={{ width: '100%', padding: '10px', marginTop: '5px' }}
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label>🔒 Mot de passe *</label>
          <input
            type="password"
            name="password"
            value={formData.password}
            onChange={handleInputChange}
            required
            style={{ width: '100%', padding: '10px', marginTop: '5px' }}
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label>🎭 Rôle *</label>
          <select
            name="role"
            value={formData.role}
            onChange={handleInputChange}
            required
            style={{ width: '100%', padding: '10px', marginTop: '5px' }}
          >
            <option value="">Sélectionnez un rôle</option>
            <option value="student">Étudiant</option>
            <option value="teacher">Professeur</option>
          </select>
        </div>

        {/* Champ classe - seulement visible pour les étudiants */}
        {formData.role === 'student' && (
          <div style={{ marginBottom: '15px' }}>
            <label>🏫 Classe *</label>
            {classes.length === 0 ? (
              <div style={{ 
                padding: '10px', 
                backgroundColor: '#fff3cd', 
                color: '#856404',
                borderRadius: '5px',
                marginTop: '5px'
              }}>
                ⚠️ Aucune classe disponible. Contactez l'administrateur.
              </div>
            ) : (
              <select
                name="class_id"
                value={formData.class_id}
                onChange={handleInputChange}
                required
                style={{ width: '100%', padding: '10px', marginTop: '5px' }}
              >
                <option value="">Sélectionnez une classe</option>
                {classes.map(classe => (
                  <option key={classe.id} value={classe.id}>
                    {classe.name} - {classe.niveau} ({classe.annee_scolaire})
                  </option>
                ))}
              </select>
            )}
          </div>
        )}

        <button 
          type="submit" 
          disabled={loading}
          style={{
            width: '100%',
            padding: '12px',
            backgroundColor: loading ? '#6c757d' : '#007bff',
            color: 'white',
            border: 'none',
            borderRadius: '5px',
            cursor: loading ? 'not-allowed' : 'pointer',
            fontSize: '16px'
          }}
        >
          {loading ? '⏳ Création...' : '📝 Créer le compte'}
        </button>
      </form>

      {/* Lien vers login */}
      <div style={{ textAlign: 'center', marginTop: '20px' }}>
        <p>Déjà un compte ? 
          <button 
            onClick={() => navigate('/login')}
            style={{
              background: 'none',
              border: 'none',
              color: '#007bff',
              cursor: 'pointer',
              textDecoration: 'underline',
              marginLeft: '5px'
            }}
          >
            Se connecter
          </button>
        </p>
      </div>
    </div>
  );
};

export default Register;
